-- Migration 004: re-add auth_verification_challenges for OTP flows
-- Reason: v4.1 dropped this table but backend AuthOtpService still needs it for
-- REGISTER_EMAIL / PASSWORD_RESET / CHANGE_EMAIL / CHANGE_PHONE challenges.
-- Adapted from v1.2 to v4.1 conventions: bigint identity PK, public schema,
-- user_id bigint FK to users(id).

BEGIN;

CREATE TABLE IF NOT EXISTS "auth_verification_challenges" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" bigint NOT NULL REFERENCES "users" ("id") ON DELETE CASCADE,
    "purpose" varchar(40) NOT NULL,
    "channel" varchar(15) NOT NULL,
    "recipient_fingerprint" bytea NOT NULL,
    "secret_hash" text NOT NULL,
    "status" varchar(20) NOT NULL DEFAULT 'PENDING',
    "attempts" integer NOT NULL DEFAULT 0,
    "max_attempts" integer NOT NULL DEFAULT 5,
    "expires_at" timestamp without time zone NOT NULL,
    "verified_at" timestamp without time zone,
    "created_at" timestamp without time zone NOT NULL DEFAULT now(),
    CONSTRAINT "ck_avc_attempts_nonneg" CHECK ("attempts" >= 0),
    CONSTRAINT "ck_avc_attempts_lte_max" CHECK ("attempts" <= "max_attempts"),
    CONSTRAINT "ck_avc_channel" CHECK ("channel" IN ('EMAIL','SMS')),
    CONSTRAINT "ck_avc_max_attempts_range" CHECK ("max_attempts" BETWEEN 1 AND 20),
    CONSTRAINT "ck_avc_purpose" CHECK ("purpose" IN ('REGISTER_EMAIL','CHANGE_EMAIL','CHANGE_PHONE','PASSWORD_RESET')),
    CONSTRAINT "ck_avc_recipient_fingerprint_len" CHECK (octet_length("recipient_fingerprint") = 32),
    CONSTRAINT "ck_avc_status" CHECK ("status" IN ('PENDING','VERIFIED','EXPIRED','LOCKED','REVOKED')),
    CONSTRAINT "ck_avc_verified_at_consistency" CHECK ("status" <> 'VERIFIED' OR "verified_at" IS NOT NULL),
    CONSTRAINT "ck_avc_expiry_after_create" CHECK ("expires_at" > "created_at")
);

CREATE INDEX IF NOT EXISTS "ix_auth_verification_challenges_user_id"     ON "auth_verification_challenges" ("user_id");
CREATE INDEX IF NOT EXISTS "ix_auth_verification_challenges_status"      ON "auth_verification_challenges" ("status");
CREATE INDEX IF NOT EXISTS "ix_auth_verification_challenges_expires_at"  ON "auth_verification_challenges" ("expires_at");

COMMIT;
